function isAccessUnlocked() {
  try {
    return localStorage.getItem(ACCESS_STORAGE_KEY) === "unlocked";
  } catch (err) {
    return false;
  }
}

function rememberAccessUnlocked() {
  try {
    localStorage.setItem(ACCESS_STORAGE_KEY, "unlocked");
  } catch (err) {
    console.warn("Не удалось сохранить доступ", err);
  }
}

function setAccessState(unlocked) {
  document.body.classList.toggle("access-unlocked", unlocked);
  document.body.classList.toggle("access-locked", !unlocked);
  const accessGate = document.getElementById("accessGate");
  if (accessGate) accessGate.hidden = unlocked;
}

function bootstrapAppOnce() {
  if (_appBootstrapped) return;
  _appBootstrapped = true;
  // Профилактическая уборка, чтобы не упереться в квоту в момент сохранения:
  // лишние автобэкапы, старые аварийные копии, осиротевшие воркспейсы
  try {
    collectStorageGarbage();
  } catch (err) {}
  bootstrapApp();
}

function initAccessGate() {
  const form = document.getElementById("accessForm");
  const input = document.getElementById("accessCodeInput");
  const error = document.getElementById("accessError");

  if (isAccessUnlocked()) {
    setAccessState(true);
    bootstrapAppOnce();
    return;
  }

  setAccessState(false);
  setTimeout(() => input?.focus(), 0);

  input?.addEventListener("input", () => {
    input.value = input.value.replace(/\D/g, "").slice(0, 4);
    input.removeAttribute("aria-invalid");
    if (error) error.hidden = true;
  });

  form?.addEventListener("submit", (event) => {
    event.preventDefault();
    const code = String(input?.value || "").trim();
    if (code === ACCESS_CODE) {
      rememberAccessUnlocked();
      setAccessState(true);
      bootstrapAppOnce();
      return;
    }
    if (error) error.hidden = false;
    input?.setAttribute("aria-invalid", "true");
    input?.focus();
    input?.select();
  });
}

function makeId(prefix = "id") {
  return (
    prefix + "-" + Date.now() + "-" + Math.random().toString(16).slice(2, 8)
  );
}

function loadProjects() {
  try {
    const saved = localStorage.getItem(PROJECTS_STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length)
        return normalizeProjects(parsed);
    }
  } catch (err) {
    console.warn("Не удалось прочитать список проектов", err);
  }

  const defaultProject = {
    id: "project-default",
    name: "УНИВЕРСАЛ / ГУРУ",
    description: "Маркетинговая операционная система на основе CSV-чеклиста",
    website: "",
    type: "Платформа",
    icon: "G",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  try {
    const legacy = localStorage.getItem(LEGACY_STORAGE_KEY);
    if (
      legacy &&
      !localStorage.getItem(WORKSPACE_STORAGE_PREFIX + defaultProject.id)
    ) {
      safeStorageSet(WORKSPACE_STORAGE_PREFIX + defaultProject.id, legacy);
    } else if (
      !localStorage.getItem(WORKSPACE_STORAGE_PREFIX + defaultProject.id)
    ) {
      safeStorageSet(
        WORKSPACE_STORAGE_PREFIX + defaultProject.id,
        JSON.stringify(structuredClone(window.GURU_SEED)),
      );
    }
  } catch (err) {
    console.warn("Не удалось выполнить миграцию старой версии", err);
  }

  safeStorageSet(
    PROJECTS_STORAGE_KEY,
    JSON.stringify(normalizeProjects([defaultProject])),
  );
  return normalizeProjects([defaultProject]);
}

function saveProjects(options = {}) {
  const { cloud = true, immediate = false } = options || {};
  projects = normalizeProjects(projects);
  const saved = safeStorageSet(PROJECTS_STORAGE_KEY, JSON.stringify(projects));
  if (cloud) {
    if (immediate) pushProjectsToSupabase();
    else scheduleProjectsCloudSync();
  }
  return saved;
}

function normalizeProjects(list = []) {
  return (Array.isArray(list) ? list : [])
    .filter((project) => project?.id)
    .map((project) => ({
      ...project,
      archived: Boolean(project.archived),
      lifecycleStatus:
        project.lifecycleStatus || (project.archived ? "archived" : "active"),
      icon: project.icon || getProjectIcon(project.name),
    }));
}

function readDeletedProjects() {
  try {
    const saved = localStorage.getItem(PROJECTS_DELETED_STORAGE_KEY);
    const parsed = saved ? JSON.parse(saved) : {};
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? parsed
      : {};
  } catch (err) {
    console.warn("Не удалось прочитать журнал удалённых проектов", err);
    return {};
  }
}

function saveDeletedProjects(deletedProjects) {
  const saved = safeStorageSet(
    PROJECTS_DELETED_STORAGE_KEY,
    JSON.stringify(deletedProjects || {}),
    { silent: true },
  );
  if (!saved) console.warn("Не удалось сохранить журнал удалённых проектов");
}

function rememberDeletedProject(projectId) {
  if (!projectId) return;
  const deletedProjects = readDeletedProjects();
  deletedProjects[projectId] = new Date().toISOString();
  saveDeletedProjects(deletedProjects);
}

function mergeDeletionLogs(localLog = {}, cloudLog = {}) {
  const merged = { ...(localLog || {}) };
  Object.entries(cloudLog || {}).forEach(([projectId, deletedAt]) => {
    if (
      !merged[projectId] ||
      String(deletedAt || "") > String(merged[projectId] || "")
    ) {
      merged[projectId] = deletedAt;
    }
  });
  return merged;
}

function projectUpdatedAt(project = {}) {
  return String(project.updatedAt || project.createdAt || "");
}

function projectRegistryUpdatedAt(
  list = projects,
  deletedProjects = readDeletedProjects(),
) {
  const dates = [
    ...normalizeProjects(list).map(projectUpdatedAt),
    ...Object.values(deletedProjects || {}).map((value) => String(value || "")),
  ]
    .filter(Boolean)
    .sort();
  return dates[dates.length - 1] || new Date().toISOString();
}

function projectRegistryPayload() {
  const deletedProjects = readDeletedProjects();
  return {
    type: "guru-project-registry",
    schemaVersion: PROJECT_REGISTRY_SCHEMA_VERSION,
    updatedAt: projectRegistryUpdatedAt(projects, deletedProjects),
    deletedProjects,
    projects: normalizeProjects(projects),
  };
}

function mergeProjectRegistries(
  localList = [],
  cloudList = [],
  deletedProjects = {},
) {
  const byId = new Map();
  [...normalizeProjects(localList), ...normalizeProjects(cloudList)].forEach(
    (project) => {
      const deletedAt = String(deletedProjects[project.id] || "");
      if (deletedAt && deletedAt >= projectUpdatedAt(project)) return;
      const existing = byId.get(project.id);
      if (
        !existing ||
        projectUpdatedAt(project) >= projectUpdatedAt(existing)
      ) {
        byId.set(project.id, project);
      }
    },
  );
  return [...byId.values()].sort((a, b) => {
    const aDate = projectUpdatedAt(a);
    const bDate = projectUpdatedAt(b);
    if (aDate !== bDate) return aDate < bDate ? 1 : -1;
    return String(a.name || "").localeCompare(String(b.name || ""), "ru");
  });
}

function applyProjectRegistryPayload(payload = {}) {
  const cloudProjects = Array.isArray(payload) ? payload : payload.projects;
  if (!Array.isArray(cloudProjects)) return false;
  const deletedProjects = mergeDeletionLogs(
    readDeletedProjects(),
    payload.deletedProjects || {},
  );
  saveDeletedProjects(deletedProjects);
  const before = JSON.stringify(normalizeProjects(projects));
  projects = mergeProjectRegistries(projects, cloudProjects, deletedProjects);
  saveProjects({ cloud: false });
  if (!els.launcher.hidden) renderProjectLauncher();
  return before !== JSON.stringify(projects);
}

function currentProjectIdSafe() {
  return activeProjectId || "";
}

function loadState(projectId) {
  const saved = localStorage.getItem(WORKSPACE_STORAGE_PREFIX + projectId);
  if (saved) {
    let parsed = null;
    try {
      parsed = JSON.parse(saved);
    } catch (err) {
      console.warn("Не удалось прочитать сохранение проекта", err);
    }
    if (parsed) {
      try {
        return migrateWorkspace(parsed, projectId);
      } catch (err) {
        // Миграция упала — сохраняем аварийную копию и возвращаем данные как есть,
        // чтобы ни в коем случае не затереть их пустым проектом
        console.error("Ошибка миграции, работаем с сырыми данными", err);
        safeStorageSet(STORAGE_RESCUE_PREFIX + projectId + "-" + Date.now(), saved, {
          silent: true,
        });
        return parsed;
      }
    }
  }
  return createFreshWorkspace(projects.find((p) => p.id === projectId));
}

function migrateWorkspace(workspace, projectId) {
  const meta = projects.find((p) => p.id === projectId);
  workspace.project = workspace.project || {};
  workspace.gates = workspace.gates || structuredClone(window.GURU_SEED.gates);
  workspace.metrics = workspace.metrics || [];
  workspace.linkBank = Array.isArray(workspace.linkBank)
    ? workspace.linkBank
    : [];
  workspace.tools = normalizeProjectTools(workspace.tools);
  if (meta) {
    workspace.project.name = workspace.project.name || meta.name;
    workspace.project.description =
      workspace.project.description || meta.description;
    workspace.project.website = workspace.project.website || meta.website;
    workspace.project.niche =
      workspace.project.niche || meta.niche || meta.type || "";
    workspace.project.geography =
      workspace.project.geography || meta.geography || "";
    workspace.project.mainCta = workspace.project.mainCta || meta.mainCta || "";
    workspace.project.usp = workspace.project.usp || meta.usp || "";
    workspace.project.offer = workspace.project.offer || meta.offer || "";
    workspace.project.afterMainCta =
      workspace.project.afterMainCta || meta.afterMainCta || "";
    workspace.project.afterUsp =
      workspace.project.afterUsp || meta.afterUsp || "";
    workspace.project.afterOffer =
      workspace.project.afterOffer || meta.afterOffer || "";
    workspace.project.afterDescription =
      workspace.project.afterDescription || meta.afterDescription || "";
  }
  prepareSystemCards(workspace);
  initializeEvidenceStructure(workspace);
  harvestKnownLinks(workspace);
  syncProjectPassportCard(workspace);
  recalculateAllStatuses(workspace);
  workspace.schemaVersion = PLATFORM_VERSION;
  return workspace;
}

function createFreshWorkspace(meta = {}) {
  const fresh = structuredClone(window.GURU_SEED);
  fresh.schemaVersion = PLATFORM_VERSION;
  fresh.project.name = meta.name || "Новый проект";
  fresh.project.description = meta.description || "";
  fresh.project.website = meta.website || "";
  fresh.project.niche = meta.niche || meta.type || "";
  fresh.project.geography = meta.geography || "";
  fresh.project.mainCta = meta.mainCta || "";
  fresh.project.usp = meta.usp || "";
  fresh.project.offer = meta.offer || "";
  fresh.project.afterMainCta = meta.afterMainCta || "";
  fresh.project.afterUsp = meta.afterUsp || "";
  fresh.project.afterOffer = meta.afterOffer || "";
  fresh.project.afterDescription = meta.afterDescription || "";
  fresh.metrics = [];
  fresh.linkBank = [];
  fresh.tools = defaultProjectTools();
  prepareSystemCards(fresh);
  initializeEvidenceStructure(fresh);
  harvestKnownLinks(fresh);
  syncProjectPassportCard(fresh);
  return fresh;
}

function saveState() {
  if (!state || !activeProjectId) return;
  syncProjectPassportCard(state);
  harvestKnownLinks(state);
  recalculateAllStatuses(state);
  syncEvidenceTexts();
  state.updatedAt = new Date().toISOString();
  state.schemaVersion = PLATFORM_VERSION;
  const saved = safeStorageSet(
    WORKSPACE_STORAGE_PREFIX + activeProjectId,
    JSON.stringify(state),
  );
  syncActiveProjectMeta();
  // При неудачной записи статус ошибки уже выставлен в reportStorageFailure —
  // не перекрываем его сообщением об успехе
  if (saved) {
    els.saveStatus.textContent =
      "Сохранено: " +
      new Date().toLocaleTimeString("ru-RU", {
        hour: "2-digit",
        minute: "2-digit",
      });
    els.autosaveDot.style.background = "#82d48d";
  }
  scheduleCloudSync();
  return saved;
}

function syncActiveProjectMeta() {
  const project = projects.find((p) => p.id === activeProjectId);
  if (!project || !state?.project) return;
  project.name = state.project.name || project.name;
  project.description = state.project.description || project.description;
  project.website = state.project.website || project.website;
  project.niche = state.project.niche || project.niche || project.type || "";
  project.type = state.project.niche || project.type || "";
  project.geography = state.project.geography || project.geography || "";
  project.mainCta = state.project.mainCta || project.mainCta || "";
  project.usp = state.project.usp || project.usp || "";
  project.offer = state.project.offer || project.offer || "";
  project.afterMainCta =
    state.project.afterMainCta || project.afterMainCta || "";
  project.afterUsp = state.project.afterUsp || project.afterUsp || "";
  project.afterOffer = state.project.afterOffer || project.afterOffer || "";
  project.afterDescription =
    state.project.afterDescription || project.afterDescription || "";
  project.updatedAt = new Date().toISOString();
  project.icon = project.icon || getProjectIcon(project.name);
  saveProjects();
}

function flashSaving() {
  if (!state) return;
  els.saveStatus.textContent = "Сохраняю...";
  els.autosaveDot.style.background = "#d4b05f";
  setTimeout(saveState, 120);
}

function showLauncher() {
  activeProjectId = null;
  state = null;
  activeView = "project";
  activeGateId = null;
  els.appShell.hidden = true;
  els.launcher.hidden = false;
  renderProjectLauncher();
}

function openProject(projectId) {
  const localRaw = localStorage.getItem(WORKSPACE_STORAGE_PREFIX + projectId);
  const hadLocalWorkspace = Boolean(localRaw);
  activeProjectId = projectId;
  state = loadState(projectId);
  activeView = "project";
  activeGateId = state.gates[0]?.id || null;
  els.launcher.hidden = true;
  els.appShell.hidden = false;
  render();
  loadFromSupabase(projectId).then((cloudResult) => {
    if (activeProjectId !== projectId) return;
    if (!cloudResult) {
      // Реестр проекта может существовать без workspace. Не отправляем
      // автоматически созданный пустой seed поверх возможных данных.
      if (hadLocalWorkspace) pushToSupabase(projectId, state);
      else {
        els.saveStatus.textContent = "Данных проекта пока нет";
        els.autosaveDot.style.background = "#d4b05f";
      }
      return;
    }
    const cloudState = cloudResult.state;
    _cloudWorkspaceVersions.set(projectId, cloudResult.cloudUpdatedAt || "");
    const local = state?.updatedAt || "";
    const cloud = cloudState.updatedAt || "";
    if (!hadLocalWorkspace || cloud > local) {
      if (hadLocalWorkspace && localRaw) {
        safeStorageSet(
          STORAGE_BACKUP_PREFIX + projectId + "-before-cloud-" + Date.now(),
          localRaw,
          { silent: true },
        );
      }
      state = migrateWorkspace(cloudState, projectId);
      safeStorageSet(
        WORKSPACE_STORAGE_PREFIX + projectId,
        JSON.stringify(state),
      );
      syncActiveProjectMeta();
      render();
      els.saveStatus.textContent = "Загружено из облака";
      els.autosaveDot.style.background = "#4a9eff";
    } else if (local > cloud) {
      pushToSupabase(projectId, state);
    } else {
      els.saveStatus.textContent = "Синхронизировано с облаком";
      els.autosaveDot.style.background = "#4a9eff";
    }
  });
}

function renderProjectLauncher() {
  projects = normalizeProjects(projects);
  const activeProjects = projects.filter((project) => !project.archived);
  const archivedProjects = projects.filter((project) => project.archived);
  const visibleProjects =
    launcherProjectFilter === "archive" ? archivedProjects : activeProjects;
  const emptyMessage =
    launcherProjectFilter === "archive"
      ? '<div class="project-empty">Архив пуст. Здесь будут проекты, которые вы скрыли без удаления данных.</div>'
      : '<div class="project-empty">Активных проектов пока нет.</div>';

  document.querySelectorAll("[data-project-filter]").forEach((btn) => {
    btn.classList.toggle(
      "is-active",
      btn.dataset.projectFilter === launcherProjectFilter,
    );
    const count =
      btn.dataset.projectFilter === "archive"
        ? archivedProjects.length
        : activeProjects.length;
    btn.querySelector("[data-filter-count]").textContent = String(count);
  });

  els.projectGrid.innerHTML =
    (visibleProjects.length
      ? visibleProjects.map(projectCardHtml).join("")
      : emptyMessage) +
    (launcherProjectFilter === "active" ? addProjectCardHtml() : "");

  document.querySelectorAll("[data-open-project]").forEach((card) => {
    card.addEventListener("click", (e) => {
      if (
        e.target.closest(
          "[data-project-menu], [data-project-action], [data-project-site], .project-menu-panel",
        )
      )
        return;
      openProject(card.dataset.openProject);
    });
    card.addEventListener("keydown", (e) => {
      if (
        (e.key === "Enter" || e.key === " ") &&
        !e.target.closest("button, a")
      ) {
        e.preventDefault();
        openProject(card.dataset.openProject);
      }
    });
  });
  document.querySelectorAll("[data-project-site]").forEach((link) => {
    link.addEventListener("click", (e) => e.stopPropagation());
  });
  document.querySelectorAll("[data-project-menu]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleProjectMenu(btn.dataset.projectMenu);
    });
  });
  document.querySelectorAll("[data-project-action]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      handleProjectMenuAction(btn.dataset.projectAction, btn.dataset.projectId);
    });
  });
  document
    .getElementById("addProjectCard")
    ?.addEventListener("click", showNewProjectModal);
}

function projectCardHtml(project) {
  const website = project.website ? normalizeUrl(project.website) : "";
  const description =
    project.description || "Короткое описание проекта пока не заполнено.";
  const isArchived = Boolean(project.archived);
  return `
    <div class="project-card ${isArchived ? "project-card-archived" : ""}" data-open-project="${escapeAttr(project.id)}" tabindex="0" role="button" aria-label="Открыть проект ${escapeAttr(project.name)}">
      <button type="button" class="project-menu-trigger" data-project-menu="${escapeAttr(project.id)}" aria-label="Меню проекта">⋯</button>
      <div class="project-menu-panel" data-project-menu-panel="${escapeAttr(project.id)}" hidden>
        <button type="button" data-project-action="open" data-project-id="${escapeAttr(project.id)}">Открыть проект</button>
        <button type="button" data-project-action="edit-passport" data-project-id="${escapeAttr(project.id)}">Редактировать паспорт</button>
        <button type="button" data-project-action="export-debug" data-project-id="${escapeAttr(project.id)}">Экспорт диагностики проекта</button>
        ${
          isArchived
            ? `<button type="button" data-project-action="restore" data-project-id="${escapeAttr(project.id)}">Вернуть из архива</button>`
            : `<button type="button" data-project-action="archive" data-project-id="${escapeAttr(project.id)}">Архивировать</button>`
        }
        <button type="button" class="danger" data-project-action="delete" data-project-id="${escapeAttr(project.id)}">Удалить проект</button>
      </div>
      <span class="project-avatar">${escapeHtml(project.icon || getProjectIcon(project.name))}</span>
      <span class="project-name">${escapeHtml(project.name)}</span>
      <span class="project-description">${escapeHtml(description)}</span>
      ${isArchived ? `<span class="project-state-chip">Архив</span>` : ""}
      ${website ? `<a class="project-site" href="${escapeAttr(website)}" target="_blank" rel="noopener" data-project-site>Открыть сайт ↗</a>` : `<span class="project-site muted-link">Ссылка не указана</span>`}
    </div>`;
}

function addProjectCardHtml() {
  return `
    <button class="project-card project-card-add" id="addProjectCard">
      <span class="project-avatar add-avatar">+</span>
      <span class="project-name">Новый проект</span>
      <span class="project-description">Создать отдельный рабочий интерфейс для нового сайта, бренда или кампании.</span>
      <span class="project-site muted-link">Добавить проект</span>
    </button>`;
}

function toggleProjectMenu(projectId) {
  activeProjectMenuId = activeProjectMenuId === projectId ? null : projectId;
  document.querySelectorAll("[data-project-menu-panel]").forEach((panel) => {
    panel.hidden = panel.dataset.projectMenuPanel !== activeProjectMenuId;
  });
}

function closeProjectMenus() {
  activeProjectMenuId = null;
  document.querySelectorAll("[data-project-menu-panel]").forEach((panel) => {
    panel.hidden = true;
  });
}

function handleProjectMenuAction(action, projectId) {
  closeProjectMenus();
  if (!projectId) return;
  if (action === "open") openProject(projectId);
  if (action === "edit-passport") openProject(projectId);
  if (action === "export-debug") exportProjectDebug(projectId);
  if (action === "archive") archiveProject(projectId);
  if (action === "restore") restoreProject(projectId);
  if (action === "delete") showProjectDeleteModal(projectId);
}

function archiveProject(projectId) {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;
  project.archived = true;
  project.lifecycleStatus = "archived";
  project.updatedAt = new Date().toISOString();
  saveProjects({ immediate: true });
  launcherProjectFilter = "active";
  renderProjectLauncher();
}

function restoreProject(projectId) {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;
  project.archived = false;
  project.lifecycleStatus = "active";
  project.updatedAt = new Date().toISOString();
  saveProjects({ immediate: true });
  launcherProjectFilter = "archive";
  renderProjectLauncher();
}

function readWorkspaceRaw(projectId) {
  try {
    const saved = localStorage.getItem(WORKSPACE_STORAGE_PREFIX + projectId);
    return saved ? JSON.parse(saved) : null;
  } catch (error) {
    return { readError: String(error?.message || error) };
  }
}

function projectDebugPayload(projectId) {
  const project = projects.find((p) => p.id === projectId) || null;
  const workspace = readWorkspaceRaw(projectId);
  const gates = Array.isArray(workspace?.gates)
    ? workspace.gates.map((gate) => ({
        id: gate.id,
        title: gate.title,
        cards: (gate.cards || []).map((card) => ({
          id: card.id,
          title: card.title,
          status: card.status,
          evidence: card.evidence || "",
          evidenceFields: ensureEvidenceFields
            ? ensureEvidenceFields(card).map((field) => ({
                key: field.key,
                label: field.label,
                value: workspace?.sharedEvidence?.[field.key] || "",
              }))
            : [],
        })),
      }))
    : [];
  return {
    tool: "GURU Debug Export",
    exportType: "project",
    schemaVersion: "v1.1.10-project-debug",
    updatedAt: new Date().toISOString(),
    projectId,
    project,
    workspaceProject: workspace?.project || {},
    lifecycleStatus: project?.archived ? "archived" : "active",
    globalData: workspace?.project || {},
    sharedEvidence: workspace?.sharedEvidence || {},
    gates,
    metrics: workspace?.metrics || [],
    linkBank: workspace?.linkBank || [],
    tools: workspace?.tools || {},
    uiState: {
      launcherProjectFilter,
      activeProjectId,
      activeView,
      activeGateId,
      url: location.href,
      viewport: { width: window.innerWidth, height: window.innerHeight },
    },
    technical: {
      platformVersion: PLATFORM_VERSION,
      localStorageKey: WORKSPACE_STORAGE_PREFIX + projectId,
      userAgent: navigator.userAgent,
    },
    notes: "Экспорт диагностики проекта перед архивированием или удалением.",
  };
}

function exportProjectDebug(projectId) {
  const project = projects.find((p) => p.id === projectId);
  const payload = projectDebugPayload(projectId);
  const slug = guruDebugSlug
    ? guruDebugSlug(project?.name || projectId)
    : String(project?.name || projectId)
        .toLowerCase()
        .replace(/\s+/g, "-");
  const filename = `guru-debug_project-${slug}_${guruDebugDateStamp ? guruDebugDateStamp() : new Date().toISOString().slice(0, 10)}.json`;
  const text =
    typeof guruDebugJsonTextV119 === "function"
      ? guruDebugJsonTextV119(payload)
      : JSON.stringify(payload, null, 2);
  if (typeof guruDebugForceDownloadV119 === "function")
    guruDebugForceDownloadV119(filename, text);
  else downloadText(filename, text);
  if (typeof guruDebugShowPanelV119 === "function")
    guruDebugShowPanelV119(filename, text);
}

function showProjectDeleteModal(projectId) {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;
  pendingDeleteProjectId = projectId;
  const modal = document.getElementById("projectDeleteModal");
  document.getElementById("deleteProjectName").textContent = project.name;
  document.getElementById("deleteProjectConfirmName").value = "";
  document.getElementById("confirmProjectDelete").disabled = true;
  modal.hidden = false;
  setTimeout(
    () => document.getElementById("deleteProjectConfirmName").focus(),
    0,
  );
}

function hideProjectDeleteModal() {
  pendingDeleteProjectId = null;
  const modal = document.getElementById("projectDeleteModal");
  if (modal) modal.hidden = true;
}

function updateDeleteConfirmState() {
  const project = projects.find((p) => p.id === pendingDeleteProjectId);
  const input = document.getElementById("deleteProjectConfirmName");
  const btn = document.getElementById("confirmProjectDelete");
  if (!project || !input || !btn) return;
  btn.disabled = input.value.trim() !== project.name;
}

function deleteProjectForever(projectId) {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;
  rememberDeletedProject(projectId);
  project.lifecycleStatus = "deleting";
  project.updatedAt = new Date().toISOString();
  saveProjects({ cloud: false });
  localStorage.removeItem(WORKSPACE_STORAGE_PREFIX + projectId);
  projects = projects.filter((p) => p.id !== projectId);
  saveProjects({ immediate: true });
  deleteWorkspaceFromSupabase(projectId);
  if (activeProjectId === projectId) {
    showLauncher();
  } else {
    hideProjectDeleteModal();
    renderProjectLauncher();
  }
}

function getProjectIcon(name = "") {
  const trimmed = String(name).trim();
  return (trimmed[0] || "G").toUpperCase();
}

function normalizeUrl(url) {
  const value = String(url || "").trim();
  if (!value) return "";
  return /^https?:\/\//i.test(value) ? value : "https://" + value;
}

function showNewProjectModal() {
  document.getElementById("newProjectName").value = "";
  document.getElementById("newProjectType").value = "";
  document.getElementById("newProjectDescription").value = "";
  document.getElementById("newProjectWebsite").value = "";
  document.getElementById("newProjectGeography").value = "";
  document.getElementById("newProjectMainCta").value = "";
  document.getElementById("newProjectUsp").value = "";
  document.getElementById("newProjectOffer").value = "";
  document.getElementById("newProjectIcon").value = "";
  els.newProjectModal.hidden = false;
  setTimeout(() => document.getElementById("newProjectName").focus(), 0);
}

function hideNewProjectModal() {
  els.newProjectModal.hidden = true;
}

function createProjectFromModal() {
  const name = document.getElementById("newProjectName").value.trim();
  const type = document.getElementById("newProjectType").value.trim();
  const description = document
    .getElementById("newProjectDescription")
    .value.trim();
  const website = document.getElementById("newProjectWebsite").value.trim();
  const geography = document.getElementById("newProjectGeography").value.trim();
  const mainCta = document.getElementById("newProjectMainCta").value.trim();
  const usp = document.getElementById("newProjectUsp").value.trim();
  const offer = document.getElementById("newProjectOffer").value.trim();
  const icon = document
    .getElementById("newProjectIcon")
    .value.trim()
    .slice(0, 2)
    .toUpperCase();
  if (!name) {
    alert("Введите название проекта.");
    return;
  }
  const project = {
    id: makeId("project"),
    name,
    type,
    niche: type,
    description,
    website,
    geography,
    mainCta,
    usp,
    offer,
    afterMainCta: "",
    afterUsp: "",
    afterOffer: "",
    afterDescription: "",
    icon: icon || getProjectIcon(name),
    archived: false,
    lifecycleStatus: "active",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  projects.push(project);
  // Сначала пишем крупный воркспейс, затем компактный реестр: если места нет,
  // падает первая запись и реестр остаётся нетронутым. Полусозданный проект
  // откатываем целиком — без «призраков», которые видны, но не открываются
  const workspace = createFreshWorkspace(project);
  const workspaceSaved = safeStorageSet(
    WORKSPACE_STORAGE_PREFIX + project.id,
    JSON.stringify(workspace),
  );
  const registrySaved = workspaceSaved && saveProjects({ immediate: true });
  if (!workspaceSaved || !registrySaved) {
    projects = projects.filter((p) => p.id !== project.id);
    try {
      localStorage.removeItem(WORKSPACE_STORAGE_PREFIX + project.id);
    } catch (err) {}
    if (workspaceSaved) saveProjects({ cloud: false });
    return;
  }
  pushToSupabase(project.id, workspace, { silent: true });
  hideNewProjectModal();
  openProject(project.id);
}

function allCards() {
  return state.gates.flatMap((g) =>
    g.cards.map((c) => ({ ...c, gateId: g.id, gateTitle: g.title })),
  );
}

function countByStatus(cards = allCards()) {
  return cards.reduce((acc, c) => {
    acc[c.status] = (acc[c.status] || 0) + 1;
    return acc;
  }, {});
}

