function g5StructureTable() {
  const g5 = ensureGate5State();
  const rows = Object.values(g5.setup.ads)
    .slice(0, 80)
    .map(
      (a) =>
        `<tr><td>${g5Esc(a.campaignId)}</td><td>${g5Esc(g5.setup.campaigns[a.campaignId]?.name || "—")}</td><td>${g5Esc(a.groupId)}</td><td>${g5Esc(g5.setup.groups[a.groupId]?.name || "—")}</td><td>${g5Esc(a.id)}</td><td>${g5Esc(a.title)}</td></tr>`,
    )
    .join("");
  const empty = Object.keys(g5.setup.ads).length
    ? ""
    : '<tr><td colspan="6">Структура ещё не импортирована.</td></tr>';
  return `<div class="gate5-table-wrap"><table class="gate5-table"><thead><tr><th>№ кампании</th><th>Кампания</th><th>№ группы</th><th>Группа</th><th>№ объявления</th><th>Объявление</th></tr></thead><tbody>${rows || empty}</tbody></table></div>`;
}
function g5UploadStatusHtml(meta, totalRows) {
  if (!meta || !meta.uploadedAt) {
    return '<div class="gate5-upload-status"><span class="status-pill status-not_started">Не загружен</span></div>';
  }
  const uploads = Array.isArray(meta.uploads) ? meta.uploads : [];
  const history = uploads
    .slice()
    .reverse()
    .map(
      (u) =>
        `<div class="gate5-upload-row"><span class="gate5-upload-file">${g5Esc(u.fileName || "файл")}</span><span class="gate5-muted">${g5DateTime(u.uploadedAt)} · строк: ${g5Int(u.rows)}${u.from ? ` · период ${g5Esc(u.from)} — ${g5Esc(u.to)}` : ""}</span></div>`,
    )
    .join("");
  return `<div class="gate5-upload-status"><span class="status-pill status-ready">Загружен</span><span class="gate5-muted">${g5DateTime(meta.uploadedAt)}${totalRows != null ? ` · всего строк: ${g5Int(totalRows)}` : ""}</span></div>${history ? `<div class="gate5-upload-history">${history}</div>` : ""}`;
}
function renderGate5Input() {
  const g5 = ensureGate5State();
  return `<div class="gate5-report-list">${Object.entries(GATE5_REPORTS)
    .map(([key, rep]) => {
      const meta = g5.imports[key];
      return `<div class="gate5-report-card"><h4>${g5Esc(rep.title)}</h4><small>${g5Esc(rep.desc)}</small>${g5UploadStatusHtml(meta, g5.reports[key]?.length)}<div class="gate5-fileline"><label class="gate5-field">${meta ? "Догрузить файл (данные суммируются)" : "Файл"}<input type="file" data-gate5-import="${g5Attr(key)}" accept=".xlsx,.xls,.csv,.tsv,.txt"></label><button class="btn secondary" data-gate5-clear="${g5Attr(key)}">Очистить</button></div></div>`;
    })
    .join("")}</div>${g5GoalFormAndHistory()}`;
}
function g5GoalFormAndHistory() {
  const goal = g5ActiveGoal();
  const rows = ensureGate5State()
    .goals.slice()
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))
    .map(
      (g) =>
        `<tr><td>${g5DateTime(g.createdAt)}</td><td>${g5Int(g.leads)}</td><td>${g5Rub(g.cpa)}</td><td>${g5Rub(g.cac)}</td><td>${g.drr ? g.drr + "%" : "—"}</td><td>${g5Esc(g.comment || "—")}</td></tr>`,
    )
    .join("");
  return `<div class="gate5-card" style="margin-top:12px"><h4>Цели</h4><p>Цели нужны, чтобы статусы стали управленческими, а не просто отчётными.</p><div class="gate5-grid-4" style="margin-top:12px">
    <label class="gate5-field">Лиды<input data-gate5-goal="leads" inputmode="numeric"></label>
    <label class="gate5-field">CPA ₽<input data-gate5-goal="cpa" inputmode="decimal"></label>
    <label class="gate5-field">CAC ₽<input data-gate5-goal="cac" inputmode="decimal"></label>
    <label class="gate5-field">DRR %<input data-gate5-goal="drr" inputmode="decimal"></label>
  </div><label class="gate5-field" style="margin-top:12px">Комментарий (необязательно)<input data-gate5-goal="comment"></label><div class="gate5-actions"><button class="btn primary" data-gate5-save-goal>Сохранить цель</button></div>${goal ? `<div class="gate5-note gate5-good">Активная цель: ${g5Int(goal.leads)} лидов · CPA ${g5Rub(goal.cpa)} · CAC ${g5Rub(goal.cac)} · DRR ${goal.drr || "—"}%</div>` : '<div class="gate5-note">Цель ещё не задана.</div>'}</div><div class="gate5-table-wrap"><table class="gate5-table"><thead><tr><th>Дата</th><th>Лиды</th><th>CPA</th><th>CAC</th><th>DRR</th><th>Комментарий</th></tr></thead><tbody>${rows || '<tr><td colspan="6">Истории целей пока нет.</td></tr>'}</tbody></table></div>`;
}
function renderGate5Ad() {
  const model = g5BuildModel();
  const rows = Object.values(model.campaigns)
    .filter((x) => x.spend || x.clicks || x.conversions)
    .sort((a, b) => b.spend - a.spend)
    .map((c) => {
      const r = g5RowMetrics(c);
      const st = g5AdRowStatus(c);
      return `<tr><td><b>${g5Esc(c.name)}</b><br><span class="gate5-muted">${g5Esc(c.id)}</span></td><td>${r.spend}</td><td>${r.impressions}</td><td>${r.clicks}</td><td>${r.ctr}</td><td>${r.conversions}</td><td>${r.cr}</td><td>${r.cpa}</td><td><span class="status-pill status-${st}">${g5Esc(STATUS_LABELS[st] || st)}</span></td></tr>`;
    })
    .join("");
  const problemQueries = ensureGate5State()
    .reports.query.filter((q) => q.spend && !q.conversions)
    .sort((a, b) => b.spend - a.spend)
    .slice(0, 30);
  return `<div class="gate5-table-wrap"><table class="gate5-table"><thead><tr><th>Кампания</th><th>Расход</th><th>Показы</th><th>Клики</th><th>CTR</th><th>Лиды</th><th>CR</th><th>CPA</th><th>Статус</th></tr></thead><tbody>${rows || '<tr><td colspan="9">Отчёт рекламы ещё не загружен.</td></tr>'}</tbody></table></div><h4 style="margin-top:16px">Проблемные зоны</h4>${g5ProblemsTable(problemQueries)}`;
}
function g5AdRowStatus(row) {
  const goal = g5ActiveGoal();
  const m = g5Metrics(row);
  if (goal?.cpa && m.cpa && m.cpa > goal.cpa) return "problem";
  if (m.conversions) return "ready";
  if (m.spend) return "needs_review";
  return "in_progress";
}
function g5ProblemsTable(rows) {
  return `<div class="gate5-table-wrap"><table class="gate5-table"><thead><tr><th>Запрос / условие</th><th>Кампания</th><th>Расход</th><th>Клики</th><th>Лиды</th><th>Решение</th></tr></thead><tbody>${rows.map((q) => `<tr><td>${g5Esc(q.query || q.conditionName || "—")}</td><td>${g5Esc(q.campaignName || q.campaignId || "—")}</td><td>${g5Rub(q.spend)}</td><td>${g5Int(q.clicks)}</td><td>${g5Int(q.conversions)}</td><td><span class="status-pill status-needs_review">Проверить / минусовать</span></td></tr>`).join("") || '<tr><td colspan="6">Проблемные запросы появятся после загрузки отчёта поисковых запросов.</td></tr>'}</tbody></table></div>`;
}
function renderGate5Bridge() {
  const f = g5Finance();
  const link = g5LatestLink();
  const rows = ensureGate5State()
    .links.slice()
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))
    .map((l) => {
      const revenue =
        g5Num(l.actualRevenue) ||
        g5Num(l.orders) * (g5Num(l.avgCheck) || g5Num(l.minCheck));
      const cac = g5Div(g5Num(l.adSpend), g5Num(l.orders));
      return `<tr><td>${g5DateTime(l.createdAt)}</td><td>${g5Int(l.leads)}</td><td>${g5Int(l.orders)}</td><td>${g5Pct(g5Div(l.orders, l.leads))}</td><td>${g5Rub(l.adSpend)}</td><td>${g5Rub(cac)}</td><td>${g5Rub(revenue)}</td><td>${g5Esc(l.comment || "—")}</td></tr>`;
    })
    .join("");
  return `<div class="gate5-grid-4"><label class="gate5-field">Лиды<input data-gate5-link="leads" value="${g5Attr(f.leads)}"></label><label class="gate5-field">Заказы<input data-gate5-link="orders" inputmode="numeric"></label><label class="gate5-field">Средний чек ₽<input data-gate5-link="avgCheck" inputmode="decimal"></label><label class="gate5-field">Фактическая выручка ₽<input data-gate5-link="actualRevenue" inputmode="decimal"></label></div><div class="gate5-grid-4" style="margin-top:12px"><label class="gate5-field">Расход рекламы<input data-gate5-link="adSpend" value="${g5Attr(Math.round(f.spend))}"></label><label class="gate5-field">Маржинальность %<input data-gate5-link="margin" inputmode="decimal"></label><label class="gate5-field">Минимальный чек ₽<input data-gate5-link="minCheck" inputmode="decimal"></label><label class="gate5-field">Комментарий (необязательно)<input data-gate5-link="comment"></label></div><div class="gate5-actions"><button class="btn primary" data-gate5-save-link>Сохранить связку</button></div>${link ? `<div class="gate5-note gate5-good">Последняя связка: ${g5Int(link.leads)} лидов → ${g5Int(link.orders)} заказов.</div>` : '<div class="gate5-note">Связка с заказами ещё не сохранена.</div>'}<div class="gate5-table-wrap"><table class="gate5-table"><thead><tr><th>Дата</th><th>Лиды</th><th>Заказы</th><th>Лид → заказ</th><th>Расход</th><th>CAC</th><th>Выручка</th><th>Комментарий</th></tr></thead><tbody>${rows || '<tr><td colspan="8">Истории связки пока нет.</td></tr>'}</tbody></table></div>`;
}
function renderGate5Finance() {
  const f = g5Finance();
  const goal = g5ActiveGoal();
  const status = getGate5Status();
  let decision = "Нет данных для решения";
  if (f.revenue && status === "ready") decision = "Масштабировать / удерживать";
  if (f.revenue && status === "problem")
    decision = "Оптимизировать или остановить";
  if (f.spend && !f.revenue) decision = "Нужна связка с заказами";
  return `<div class="gate5-grid-4"><div class="gate5-kpi"><span>CPA</span><strong>${f.cpa ? g5Rub(f.cpa) : "—"}</strong><small>цель ${goal?.cpa ? g5Rub(goal.cpa) : "—"}</small></div><div class="gate5-kpi"><span>CAC</span><strong>${f.cac ? g5Rub(f.cac) : "—"}</strong><small>цель ${goal?.cac ? g5Rub(goal.cac) : "—"}</small></div><div class="gate5-kpi"><span>ROAS</span><strong>${f.roas ? f.roas.toFixed(2).replace(".", ",") + "×" : "—"}</strong><small>выручка / расход</small></div><div class="gate5-kpi"><span>DRR</span><strong>${f.drr ? g5Pct(f.drr) : "—"}</strong><small>цель ${goal?.drr ? goal.drr + "%" : "—"}</small></div></div><div class="gate5-decision ${status === "problem" ? "gate5-problem" : status === "ready" ? "gate5-good" : "gate5-warning"}" style="margin-top:16px"><strong>${g5Esc(decision)}</strong><p class="gate5-muted">ROI: ${f.spend ? g5Pct(f.roi) : "—"}. Решение строится из связки: рекламные отчёты → цели → лиды → заказы → выручка.</p></div>${g5FinanceChecks()}`;
}
function g5FinanceChecks() {
  const f = g5Finance();
  const goal = g5ActiveGoal();
  const checks = [];
  if (!f.spend)
    checks.push(["not_started", "Нет загруженных рекламных отчётов."]);
  if (!goal) checks.push(["in_progress", "Нет целей CPA / CAC / DRR."]);
  if (!g5LatestLink())
    checks.push(["in_progress", "Нет связки лидов с заказами и выручкой."]);
  if (goal?.cpa && f.cpa > goal.cpa)
    checks.push(["problem", "CPA выше допустимого значения."]);
  if (goal?.cac && f.cac > goal.cac)
    checks.push(["problem", "CAC выше допустимого значения."]);
  if (goal?.drr && f.drr > goal.drr / 100)
    checks.push(["problem", "DRR выше допустимого значения."]);
  if (!checks.length)
    checks.push(["ready", "Критичных финансовых проблем не найдено."]);
  return `<div class="gate5-checks">${checks.map(([st, text]) => `<div class="gate5-check"><span class="status-pill status-${st}">${g5Esc(STATUS_LABELS[st] || st)}</span> ${g5Esc(text)}</div>`).join("")}</div>`;
}
function renderGate5Journal() {
  const g5 = ensureGate5State();
  const iters = g5.iterations.slice().reverse();
  const GATE4_BLOCKS = ["Посадочная", "Креатив", "Параметры кампании", "Оффер"];
  const METRICS = ["CPL", "Конверсия", "CTR", "CPA", "CAC", "DRR", "ROAS"];
  const SOURCES = ["Метрика", "CRM", "Вручную", "Рекламный кабинет"];
  const VERDICTS = {
    worked: "Сработало",
    not_worked: "Не сработало",
    next: "Нужна следующая итерация",
  };
  const nextNum = g5.iterationCounter + 1;
  const form = `<div class="gate5-card" style="margin-bottom:16px">
    <h4>Новая итерация #${nextNum}</h4>
    <div class="gate5-iter-section"><strong>1. Триггер итерации</strong></div>
    <div class="gate5-grid-2" style="margin-top:8px">
      <label class="gate5-field">Дата обнаружения<input type="date" data-g5iter="triggerDate" value="${new Date().toISOString().slice(0, 10)}"></label>
      <label class="gate5-field">Источник сигнала<select data-g5iter="triggerSource">${SOURCES.map((s) => `<option>${g5Esc(s)}</option>`).join("")}</select></label>
    </div>
    <label class="gate5-field" style="margin-top:8px">Проблема одной строкой<input data-g5iter="triggerProblem" placeholder="Что обнаружили"></label>
    <label class="gate5-field" style="margin-top:8px">Затронутый блок Gate 4<select data-g5iter="triggerGate4Block">${GATE4_BLOCKS.map((b) => `<option>${g5Esc(b)}</option>`).join("")}</select></label>
    <div class="gate5-iter-section" style="margin-top:16px"><strong>2. Решение и изменения</strong></div>
    <div class="gate5-grid-2" style="margin-top:8px">
      <label class="gate5-field">Что изменено<select data-g5iter="changeType">${GATE4_BLOCKS.map((b) => `<option>${g5Esc(b)}</option>`).join("")}</select></label>
      <label class="gate5-field">Дата внесения<input type="date" data-g5iter="changeDate" value="${new Date().toISOString().slice(0, 10)}"></label>
    </div>
    <label class="gate5-field" style="margin-top:8px">Описание изменения<input data-g5iter="changeDesc" placeholder="Что конкретно изменили в Gate 4"></label>
    <div class="gate5-iter-section" style="margin-top:16px"><strong>3. Параметры проверки</strong></div>
    <div class="gate5-grid-4" style="margin-top:8px">
      <label class="gate5-field">Метрика<select data-g5iter="checkMetric">${METRICS.map((m) => `<option>${g5Esc(m)}</option>`).join("")}</select></label>
      <label class="gate5-field">Целевое значение<input data-g5iter="checkTarget" inputmode="decimal"></label>
      <label class="gate5-field">Текущее значение<input data-g5iter="checkBefore" inputmode="decimal"></label>
      <label class="gate5-field">Срок проверки<input type="date" data-g5iter="checkDeadline"></label>
    </div>
    <div class="gate5-actions" style="margin-top:12px"><button class="btn primary" data-g5iter-save>Создать итерацию</button></div>
  </div>`;
  const rows = iters
    .map((it) => {
      const hasResult = it.result && it.result.verdict;
      const verdictLabel = hasResult
        ? VERDICTS[it.result.verdict] || it.result.verdict
        : "—";
      const verdictStatus = hasResult
        ? it.result.verdict === "worked"
          ? "ready"
          : it.result.verdict === "not_worked"
            ? "problem"
            : "in_progress"
        : "not_started";
      return `<div class="gate5-card gate5-iter-entry" style="margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <h4>Итерация ${it.number} <small class="gate5-muted">${g5Esc(it.trigger.date)}</small></h4>
        <span class="status-pill status-${verdictStatus}">${g5Esc(verdictLabel)}</span>
      </div>
      <div class="gate5-grid-2" style="margin-top:8px">
        <div><small class="gate5-muted">Триггер:</small> ${g5Esc(it.trigger.problem)} <small>(${g5Esc(it.trigger.source)}, ${g5Esc(it.trigger.gate4Block)})</small></div>
        <div><small class="gate5-muted">Изменение:</small> ${g5Esc(it.change.desc)} <small>(${g5Esc(it.change.type)}, ${g5Esc(it.change.date)})</small></div>
      </div>
      <div style="margin-top:8px"><small class="gate5-muted">Проверка:</small> ${g5Esc(it.check.metric)} — цель: ${g5Esc(it.check.target)}, было: ${g5Esc(it.check.before)}, срок: ${g5Esc(it.check.deadline || "—")}</div>
      ${
        hasResult
          ? `<div style="margin-top:8px"><small class="gate5-muted">Результат:</small> факт: ${g5Esc(it.result.actual)}, ${g5Esc(verdictLabel)}${it.result.nextStep ? ". Следующий шаг: " + g5Esc(it.result.nextStep) : ""}</div>`
          : `<div class="gate5-iter-result-form" style="margin-top:8px;padding-top:8px;border-top:1px solid var(--c-border,#e0e0e0)">
        <strong>4. Результат итерации</strong>
        <div class="gate5-grid-4" style="margin-top:8px">
          <label class="gate5-field">Фактическое значение<input data-g5result="${g5Attr(it.id)}" data-g5rfield="actual" inputmode="decimal"></label>
          <label class="gate5-field">Вывод<select data-g5result="${g5Attr(it.id)}" data-g5rfield="verdict"><option value="">—</option><option value="worked">Сработало</option><option value="not_worked">Не сработало</option><option value="next">Нужна следующая итерация</option></select></label>
          <label class="gate5-field">Следующий шаг<input data-g5result="${g5Attr(it.id)}" data-g5rfield="nextStep"></label>
          <div class="gate5-field" style="display:flex;align-items:flex-end"><button class="btn secondary" data-g5result-save="${g5Attr(it.id)}">Сохранить результат</button></div>
        </div>
      </div>`
      }
    </div>`;
    })
    .join("");
  return `${form}${iters.length ? `<h4 style="margin-top:8px">История итераций (${iters.length})</h4>${rows}` : '<div class="gate5-note">Итераций пока нет. Создайте первую после цикла трафика.</div>'}`;
}
function bindGate5Events() {
  document.querySelectorAll("[data-gate5-open]").forEach((btn) =>
    btn.addEventListener("click", () => {
      const g5 = ensureGate5State();
      const key = btn.dataset.gate5Open;
      if (g5.ui.openBlocks[key]) delete g5.ui.openBlocks[key];
      else g5.ui.openBlocks[key] = true;
      saveState();
      renderGate();
    }),
  );
  document.querySelectorAll("[data-gate5-import]").forEach((input) =>
    input.addEventListener("change", async (e) => {
      const kind = e.target.dataset.gate5Import;
      const file = e.target.files?.[0];
      if (!file) return;
      try {
        const rows = await g5ReadTableFile(file);
        const ex = g5ExtractRows(
          rows,
          kind === "structure" ? "structure" : kind,
        );
        const g5 = ensureGate5State();
        if (kind === "structure") {
          g5SyncStructure(ex.records);
          g5.imports.structure = g5.imports.structure || { type: "structure", uploads: [] };
          g5.imports.structure.uploads.push({ fileName: file.name || "", uploadedAt: ex.meta.uploadedAt, rows: ex.meta.rows });
          g5.imports.structure.uploadedAt = ex.meta.uploadedAt;
        } else {
          const rowKey = (r) =>
            [r.date, r.campaignId, r.groupId, r.adId, r.query || "", r.conditionType || "", r.conditionName || ""].join("|");
          const merged = new Map((g5.reports[kind] || []).map((r) => [rowKey(r), r]));
          ex.records.forEach((r) => merged.set(rowKey(r), r));
          g5.reports[kind] = [...merged.values()];
          const imp = g5.imports[kind] || { type: kind, uploads: [] };
          if (!Array.isArray(imp.uploads)) {
            imp.uploads = imp.uploadedAt
              ? [{ fileName: "", uploadedAt: imp.uploadedAt, rows: imp.rows || 0, from: imp.from || "", to: imp.to || "" }]
              : [];
          }
          imp.uploads.push({ fileName: file.name || "", uploadedAt: ex.meta.uploadedAt, rows: ex.meta.rows, from: ex.meta.from, to: ex.meta.to });
          imp.rows = g5.reports[kind].length;
          imp.uploadedAt = ex.meta.uploadedAt;
          g5.imports[kind] = imp;
          g5SyncStructure(ex.records);
        }
        e.target.value = "";
        saveState();
        renderGate();
      } catch (err) {
        alert(err.message || "Не удалось импортировать файл");
      }
    }),
  );
  document.querySelectorAll("[data-gate5-clear]").forEach((btn) =>
    btn.addEventListener("click", () => {
      const kind = btn.dataset.gate5Clear;
      const g5 = ensureGate5State();
      if (kind === "structure") {
        g5.setup = { projectName: "", campaigns: {}, groups: {}, ads: {} };
        delete g5.imports.structure;
      } else {
        g5.reports[kind] = [];
        delete g5.imports[kind];
      }
      saveState();
      renderGate();
    }),
  );
  document
    .querySelector("[data-gate5-save-goal]")
    ?.addEventListener("click", () => {
      const goal = {
        id: makeId("g5-goal"),
        createdAt: new Date().toISOString(),
      };
      document.querySelectorAll("[data-gate5-goal]").forEach((input) => {
        goal[input.dataset.gate5Goal] = ["comment"].includes(
          input.dataset.gate5Goal,
        )
          ? input.value
          : g5Num(input.value);
      });
      ensureGate5State().goals.push(goal);
      saveState();
      renderGate();
    });
  document
    .querySelector("[data-gate5-save-link]")
    ?.addEventListener("click", () => {
      const link = {
        id: makeId("g5-link"),
        createdAt: new Date().toISOString(),
      };
      document.querySelectorAll("[data-gate5-link]").forEach((input) => {
        link[input.dataset.gate5Link] = ["comment"].includes(
          input.dataset.gate5Link,
        )
          ? input.value
          : g5Num(input.value);
      });
      ensureGate5State().links.push(link);
      saveState();
      renderGate();
    });
  document
    .querySelector("[data-g5iter-save]")
    ?.addEventListener("click", () => {
      const g5 = ensureGate5State();
      const v = (k) => {
        const el = document.querySelector(`[data-g5iter="${k}"]`);
        return el ? el.value.trim() : "";
      };
      if (!v("triggerProblem")) {
        alert("Опишите проблему одной строкой");
        return;
      }
      g5.iterationCounter = (g5.iterationCounter || 0) + 1;
      g5.iterations.push({
        id: makeId("g5-iter"),
        number: g5.iterationCounter,
        createdAt: new Date().toISOString(),
        trigger: {
          date: v("triggerDate"),
          source: v("triggerSource"),
          problem: v("triggerProblem"),
          gate4Block: v("triggerGate4Block"),
        },
        change: {
          type: v("changeType"),
          date: v("changeDate"),
          desc: v("changeDesc"),
        },
        check: {
          metric: v("checkMetric"),
          target: v("checkTarget"),
          before: v("checkBefore"),
          deadline: v("checkDeadline"),
        },
        result: null,
      });
      saveState();
      renderGate();
    });
  document.querySelectorAll("[data-g5result-save]").forEach((btn) =>
    btn.addEventListener("click", () => {
      const iterId = btn.dataset.g5resultSave;
      const g5 = ensureGate5State();
      const iter = g5.iterations.find((i) => i.id === iterId);
      if (!iter) return;
      const rv = (field) => {
        const el = document.querySelector(
          `[data-g5result="${iterId}"][data-g5rfield="${field}"]`,
        );
        return el ? el.value.trim() : "";
      };
      const verdict = rv("verdict");
      if (!verdict) {
        alert("Выберите вывод");
        return;
      }
      iter.result = {
        actual: rv("actual"),
        verdict,
        nextStep: rv("nextStep"),
        savedAt: new Date().toISOString(),
      };
      saveState();
      renderGate();
    }),
  );
}

const __guruPrevRenderGateTableV29 = renderGateTable;
renderGateTable = function (gate, cards) {
  if (gate && gate.id === "gate-5") {
    renderGate5Integrated(gate, cards);
    return;
  }
  __guruPrevRenderGateTableV29(gate, cards);
};

