function v116PassportDef(card) {
  return card ? GATE0_PASSPORT_V116_BLOCKS[card.title] : null;
}

function v116FallbackValue(field, workspace = state) {
  const project = workspace?.project || {};
  for (const key of field.fallback || []) {
    const value = String(project[key] || "").trim();
    if (value) return value;
  }
  return "";
}

function v116ReadValue(field, workspace = state) {
  return (
    workspace?.project?.[field.key] ||
    workspace?.sharedEvidence?.[field.sharedKey] ||
    v116FallbackValue(field, workspace) ||
    ""
  );
}

function v116ReadMeta(meta, workspace = state) {
  if (!meta) return "";
  return (
    workspace?.project?.[meta.key] ||
    workspace?.sharedEvidence?.[meta.sharedKey] ||
    ""
  );
}

function v116ContextRows(def, workspace = state) {
  const project = workspace?.project || {};
  const labels = {
    name: "Название",
    niche: "Ниша",
    website: "Сайт",
    geography: "География",
    whatSell: "Что продаем",
    targetSegment: "Кому продаем",
    clientResult: "Результат клиента",
    usp: "УТП",
    offer: "Офер",
    mainCta: "CTA",
    positioningStartFormula: "Стартовая формулировка",
    positioningStatement: "Позиционирование",
    offerRationalCoverage: "Рациональное покрытие",
    offerIrrationalDriver: "Иррациональный драйвер",
    offerSocialMechanism: "Социальный механизм",
  };
  return (def.context || [])
    .map((key) => [labels[key] || key, project[key]])
    .filter(([, value]) => String(value || "").trim());
}

function v116EnsureBlock(card, workspace = state) {
  const def = v116PassportDef(card);
  if (!def || !workspace) return;
  workspace.project = workspace.project || {};
  workspace.sharedEvidence = workspace.sharedEvidence || {};
  card.instruction = def.instruction;
  card.evidenceFields = [
    ...def.fields.map((field) => ({
      key: field.sharedKey,
      label: field.label,
    })),
    ...(def.tags ? [{ key: def.tags.sharedKey, label: def.tags.label }] : []),
  ];
  def.fields.forEach((field) => {
    const value = String(
      workspace.project[field.key] ||
        workspace.sharedEvidence[field.sharedKey] ||
        v116FallbackValue(field, workspace) ||
        "",
    ).trim();
    workspace.project[field.key] = value;
    workspace.sharedEvidence[field.sharedKey] = value;
  });
  [def.tags].filter(Boolean).forEach((meta) => {
    const value = String(
      workspace.project[meta.key] ||
        workspace.sharedEvidence[meta.sharedKey] ||
        "",
    ).trim();
    workspace.project[meta.key] = value;
    workspace.sharedEvidence[meta.sharedKey] = value;
  });
  card.evidence = v116Plain(card, workspace);
}

function v116EnsureAll(workspace = state) {
  if (!workspace?.gates) return;
  workspace.gates
    .flatMap((g) => g.cards || [])
    .forEach((card) => {
      if (v116PassportDef(card)) v116EnsureBlock(card, workspace);
    });
}

function v116Plain(card, workspace = state) {
  const def = v116PassportDef(card);
  if (!def) return "";
  const lines = def.fields.map(
    (field) => `${field.label}:\n${v116ReadValue(field, workspace)}`,
  );
  if (def.tags)
    lines.push(`${def.tags.label}:\n${v116ReadMeta(def.tags, workspace)}`);
  return lines.join("\n\n");
}

function v116Status(card, workspace = state) {
  const def = v116PassportDef(card);
  if (!def) return card?.status || "not_started";
  const requiredFields = guruRequiredFields(def.fields || []);
  const values = requiredFields.map((field) =>
    String(v116ReadValue(field, workspace) || "").trim(),
  );
  const filled = values.filter(Boolean).length;
  if (!filled) return "not_started";
  if (filled === requiredFields.length) return "ready";
  return "in_progress";
}

// Поля с возможностью добавлять дополнительные ячейки: ключ поля → ключ массива доп. значений
const V116_MULTI_FIELDS = {
  whatSell: {
    extraKey: "whatSellExtra",
    addLabel: "+ добавить продукт / услугу / направление",
  },
  targetSegment: {
    extraKey: "targetSegmentExtra",
    addLabel: "+ добавить сегмент / аудиторию",
  },
  clientResult: {
    extraKey: "clientResultExtra",
    addLabel: "+ добавить результат / задачу",
  },
  positioningStartFormula: {
    extraKey: "positioningStartFormulaExtra",
    addLabel: "+ добавить формулировку",
  },
  positioningStatement: {
    extraKey: "positioningStatementExtra",
    addLabel: "+ добавить позиционирование",
  },
};

function v116PassportFieldCard(def, field) {
  if (V116_MULTI_FIELDS[field.key]) return v116WhatSellCard(def, field);
  const value = v116ReadValue(field, state);
  const filled = String(value || "").trim();
  return `<label class="passport-v116-field-card">
    <span class="passport-v116-field-title">${escapeHtml(field.label)}</span>
    <span class="passport-v116-field-hint">${escapeHtml(field.hint)}</span>
    <textarea class="passport-v116-input passport-v116-autosize ${filled ? "is-filled" : "is-empty"}" data-v116-block="${escapeAttr(def.key)}" data-v116-kind="main" data-v116-key="${escapeAttr(field.key)}" placeholder="${escapeAttr(field.hint)}" rows="1">${escapeHtml(value)}</textarea>
  </label>`;
}

function v116WhatSellCard(def, field) {
  const multi = V116_MULTI_FIELDS[field.key];
  const main = v116ReadValue(field, state);
  const extra = Array.isArray(state.project?.[multi.extraKey])
    ? state.project[multi.extraKey]
    : [];
  const mainFilled = String(main || "").trim();
  // Единый список ячеек: главная (index 0) + дополнительные (index 1..N);
  // перетаскивание за ручку работает по этому сквозному индексу
  const total = extra.length + 1;
  const dragMain = guruDragRowHtml("v116", { key: multi.extraKey }, 0);
  return `<div class="passport-v116-field-card v116-multi-field">
    <span class="passport-v116-field-title">${escapeHtml(field.label)}</span>
    <span class="passport-v116-field-hint">${escapeHtml(field.hint)}</span>
    <div class="v116-multi-row" ${dragMain.rowAttrs}>
    ${total > 1 ? dragMain.handle : ""}
    <textarea class="passport-v116-input passport-v116-autosize ${mainFilled ? "is-filled" : "is-empty"}" data-v116-block="${escapeAttr(def.key)}" data-v116-kind="main" data-v116-key="${escapeAttr(field.key)}" placeholder="${escapeAttr(field.hint)}" rows="1">${escapeHtml(main)}</textarea>
    </div>
    ${extra
      .map((val, i) => {
        const f = String(val || "").trim();
        const drag = guruDragRowHtml("v116", { key: multi.extraKey }, i + 1);
        return `<div class="v116-multi-row" ${drag.rowAttrs}>
        ${drag.handle}
        <textarea class="passport-v116-input passport-v116-autosize ${f ? "is-filled" : "is-empty"}" data-v116-multi="${escapeAttr(multi.extraKey)}" data-v116-multi-idx="${i}" placeholder="${escapeAttr(field.hint)}" rows="1">${escapeHtml(val)}</textarea>
        <button class="v116-multi-remove" data-v116-multi-remove="${escapeAttr(multi.extraKey)}" data-v116-multi-idx="${i}" title="Удалить">×</button>
      </div>`;
      })
      .join("")}
    <button class="v116-multi-add" data-v116-multi-add="${escapeAttr(multi.extraKey)}">${escapeHtml(multi.addLabel)}</button>
  </div>`;
}

function v116PassportFieldsHtml(card) {
  const def = v116PassportDef(card);
  if (!def) return "";
  v116EnsureBlock(card, state);
  return `<div class="passport-v116">
    <div class="passport-v116-topline">
      <div>
        <div class="passport-v116-orient">${escapeHtml(def.orient)}</div>
      </div>
      <span class="passport-v116-status">${escapeHtml(STATUS_LABELS[v116Status(card, state)] || v116Status(card, state))}</span>
    </div>
    <div class="passport-v116-grid">
      ${def.fields.map((field) => v116PassportFieldCard(def, field)).join("")}
    </div>
    ${
      def.tags
        ? `<label class="passport-v116-tags">
      <span class="passport-v116-field-title">${escapeHtml(def.tags.label)}</span>
      <span class="passport-v116-field-hint">Короткие слова, смыслы или теги. Через запятую.</span>
      <input class="passport-v116-input" data-v116-block="${escapeAttr(def.key)}" data-v116-kind="tags" value="${escapeAttr(v116ReadMeta(def.tags, state))}" placeholder="${escapeAttr(def.tags.placeholder)}" />
    </label>`
        : ""
    }
  </div>`;
}

function v116UpdatePassportInput(e) {
  const def = Object.values(GATE0_PASSPORT_V116_BLOCKS).find(
    (item) => item.key === e.target.dataset.v116Block,
  );
  if (!def || !state) return;
  state.project = state.project || {};
  state.sharedEvidence = state.sharedEvidence || {};
  const kind = e.target.dataset.v116Kind;
  const value = e.target.value;
  if (kind === "main") {
    const field = def.fields.find(
      (item) => item.key === e.target.dataset.v116Key,
    );
    if (!field) return;
    state.project[field.key] = value;
    state.sharedEvidence[field.sharedKey] = value;
  }
  if (kind === "tags") {
    state.project[def.tags.key] = value;
    state.sharedEvidence[def.tags.sharedKey] = value;
  }
  const card = allCardsFromWorkspace(state).find((c) => c.title === def.title);
  if (card) {
    v116EnsureBlock(card, state);
    card.status = v116Status(card, state);
  }
  e.target.classList.toggle("is-filled", !!value.trim());
  e.target.classList.toggle("is-empty", !value.trim());
  flashSaving();
}

