const MEGA_TOOL_STATUSES = GURU_STATUS_OPTIONS;
const MEGA_CHANNEL_STATUSES = GURU_STATUS_OPTIONS;

function isMegaMarketingCard(card) {
  return card?.title === "Текущее состояние маркетинговой системы";
}

function ensureMegaMarketing(card, workspace = state) {
  if (!card || !isMegaMarketingCard(card)) return;
  if (!card.megaMarketing) {
    card.megaMarketing = { platform: [], infra: [], channels: [] };
    const gate = workspace?.gates?.find((g) => g.id === "gate-0");
    if (gate) {
      const oldSite = gate.cards.find(
        (c) =>
          c.title === "Текущее состояние сайта" ||
          c.title === "Текущее состояние маркетинговой системы",
      );
      const oldInfra = gate.cards.find(
        (c) => c.title === "Текущая инфраструктура маркетинга",
      );
      const oldChannels = gate.cards.find(
        (c) => c.title === "Текущие каналы и рекламные материалы",
      );
      if (oldSite?.toolItems?.length) {
        card.megaMarketing.platform = oldSite.toolItems.map((i) => ({
          name: i.name,
          status: i.status || "",
          comment: i.comment || "",
        }));
        console.log(
          "Mega migration: platform from toolItems",
          card.megaMarketing.platform.length,
        );
      }
      if (oldInfra?.toolItems?.length) {
        card.megaMarketing.infra = oldInfra.toolItems.map((i) => ({
          name: i.name,
          status: i.status || "",
          comment: i.comment || "",
        }));
        console.log(
          "Mega migration: infra from toolItems",
          card.megaMarketing.infra.length,
        );
      }
      if (oldChannels?.channelItems?.length) {
        card.megaMarketing.channels = oldChannels.channelItems.map((i) => ({
          ...i,
        }));
        console.log(
          "Mega migration: channels from channelItems",
          card.megaMarketing.channels.length,
        );
      }
    }
  }
  const m = card.megaMarketing;
  if (!m.platformV2) {
    m.platformV2 = { fundamental: [], landings: {}, extra: [] };
    if (m.platform?.length) {
      const oldMap = new Map(m.platform.map((i) => [i.name, i]));
      m.platformV2.fundamental = MEGA_PLATFORM_FUNDAMENTAL.map((name) => {
        const mapped = Object.entries(MEGA_PLATFORM_OLD_MAP).find(
          ([, v]) => v === name,
        );
        const old = mapped ? oldMap.get(mapped[0]) : oldMap.get(name);
        return {
          name,
          status: old?.status || "",
          url: old?.url || "",
          comment: old?.comment || "",
        };
      });
      console.log(
        "Platform v2 migration: fundamental",
        m.platformV2.fundamental.filter((r) => r.status).length + " with data",
      );
    }
  }
  const prevFund = new Map(m.platformV2.fundamental.map((r) => [r.name, r]));
  m.platformV2.fundamental = MEGA_PLATFORM_FUNDAMENTAL.map((name) => {
    const old = prevFund.get(name) || {};
    return {
      name,
      status: old.status || "",
      url: old.url || "",
      comment: old.comment || "",
    };
  });
  m.platformV2.landings = m.platformV2.landings || {};
  m.platformV2.extra = m.platformV2.extra || [];
  // Sync infra with v2 config, migrate old data
  const prevInfra = new Map(m.infra.map((r) => [r.name, r]));
  const infraCustom = m.infra.filter((r) => r._custom);
  m.infra = MEGA_INFRA_DEFAULTS_V2.map((cfg) => {
    let old = prevInfra.get(cfg.name);
    if (!old) {
      const mappedOldName = Object.entries(MEGA_INFRA_OLD_MAP).find(
        ([, v]) => v === cfg.name,
      );
      if (mappedOldName) old = prevInfra.get(mappedOldName[0]);
    }
    return {
      name: cfg.name,
      hint: cfg.hint,
      group: cfg.group,
      status: old?.status || "",
      comment: old?.comment || "",
    };
  });
  infraCustom.forEach((r) => m.infra.push(r));

  // Sync channels with config, preserve old data by platform+type key
  const prevCh = new Map(m.channels.map((r) => [r.platform + "|" + r.type, r]));
  const chCustom = m.channels.filter((r) => r._custom);
  m.channels = MEGA_CHANNEL_DEFAULTS.map((cfg) => {
    const old = prevCh.get(cfg.platform + "|" + cfg.type);
    return { ...cfg, status: old?.status || "" };
  });
  chCustom.forEach((r) => m.channels.push(r));

  return m;
}

