function megaPlatformProducts() {
  const main = String(state?.project?.whatSell || "").trim();
  const extra = Array.isArray(state?.project?.whatSellExtra)
    ? state.project.whatSellExtra
    : [];
  return [main, ...extra].filter(Boolean);
}

