  "Суть:\nПроверить, что Яндекс может обходить важные страницы сайта и robots.txt не содержит ошибок.\n\nКак проверить:\n1. Открыть Яндекс Вебмастер.\n2. Перейти: Инструменты → Анализ robots.txt.\n3. Нажать «Проверить».\n4. Зафиксировать количество ошибок.\n5. В блоке «Доступ к страницам» проверить важные URL: /, /services, /contacts, /catalog, /product.\n6. Отдельно проверить служебные URL: /admin, /?filter=, /cart, /login.\n7. Внести результат.\n\nИдеал:\n0 ошибок, важные страницы разрешены, служебные URL обработаны корректно.";
const ROBOTS_V2_GOOGLE_INSTRUCTION =
  "Суть:\nПроверить, что Google не заблокирован robots.txt и может увидеть ключевые страницы сайта.\n\nКак проверить:\n1. Открыть Google Search Console.\n2. Перейти в «Проверка URL».\n3. Ввести важную страницу, например главную.\n4. Запустить проверку актуальной версии.\n5. Зафиксировать, разрешено ли сканирование.\n6. Проверить, нет ли сообщения о блокировке robots.txt.\n7. При необходимости открыть просмотр страницы и зафиксировать рендер.\n8. Повторить для 2–3 ключевых страниц.\n\nИдеал:\nключевые страницы доступны для сканирования, robots.txt их не блокирует, страница рендерится без критических пустых блоков.";

function ensureRobotsV130(card) {
  if (!card) return;
  card.title = "Robots.txt: доступ поисковых роботов";
  card.instruction =
    "Проверяем, что поисковые роботы видят важные страницы сайта, а служебные URL не мешают обходу и индексации.";
  const old = card.robotsUnified || {};
  card.robotsV130 = card.robotsV130 || {
    url: old.url || "",
    domain: "",
    checkDate: "",
    source: "",
    yandex: {
      enabled: "yes",
      errors: "",
      sitemap: "",
      importantOk: "",
      serviceOk: "",
      source: "",
      urlResults: [],
      serviceResults: [],
    },
    google: {
      enabled: "yes",
      importantOk: "",
      blocked: "",
      renderOk: "",
      source: "",
      urlResults: [],
      renderPage: "",
      renderScan: "",
      renderResult: "",
      renderSource: "",
    },
    summary: {
      robotsOpen: "",
      errorsStatus: "",
      importantStatus: "",
      serviceStatus: "",
      sitemapStatus: "",
      conclusion: "",
    },
  };
  const f = card.robotsV130;
  f.yandex = f.yandex || {};
  f.google = f.google || {};
  f.summary = f.summary || {};
  if (
    !Array.isArray(f.yandex.urlResults) ||
    f.yandex.urlResults.length !== ROBOTS_V2_URL_ROWS.length
  ) {
    const prev = new Map((f.yandex.urlResults || []).map((r) => [r.url, r]));
    f.yandex.urlResults = ROBOTS_V2_URL_ROWS.map((row) => ({
      ...row,
      result: (prev.get(row.url) || {}).result || "",
    }));
  }
  if (
    !Array.isArray(f.yandex.serviceResults) ||
    f.yandex.serviceResults.length !== ROBOTS_V2_SERVICE_ROWS.length
  ) {
    const prev = new Map(
      (f.yandex.serviceResults || []).map((r) => [r.url, r]),
    );
    f.yandex.serviceResults = ROBOTS_V2_SERVICE_ROWS.map((row) => ({
      ...row,
      result: (prev.get(row.url) || {}).result || "",
      comment: (prev.get(row.url) || {}).comment || "",
    }));
  }
  if (
    !Array.isArray(f.google.urlResults) ||
    f.google.urlResults.length !== ROBOTS_V2_URL_ROWS.length
  ) {
    const prev = new Map((f.google.urlResults || []).map((r) => [r.url, r]));
    f.google.urlResults = ROBOTS_V2_URL_ROWS.map((row) => ({
      ...row,
      result: (prev.get(row.url) || {}).result || "",
    }));
  }
  return f;
}

function rv2Select(name, value, options, attrs = "") {
  return `<select ${attrs} class="g1-input ${value ? "is-filled" : "is-empty"}">${options
    .map((o) => {
      const v = Array.isArray(o) ? o[0] : o;
      const l = Array.isArray(o) ? o[1] : o || "—";
      return `<option value="${escapeAttr(v)}" ${value === v ? "selected" : ""}>${escapeHtml(l)}</option>`;
    })
    .join("")}</select>`;
}

function rv2Input(value, placeholder, attrs = "") {
  const filled = String(value || "").trim();
  return `<input class="g1-input ${filled ? "is-filled" : "is-empty"}" ${attrs} value="${escapeAttr(value || "")}" placeholder="${escapeAttr(placeholder)}" />`;
}

