function ensurePainV130() {
  state.painV130 = state.painV130 || { openSteps: {}, steps: {} };
  state.painV130.openSteps = state.painV130.openSteps || {};
  state.painV130.steps = state.painV130.steps || {};
  return state.painV130;
}

function painV130StepStatus(data, step) {
  if (step.customRender === "searchClusters") {
    const clusters = pv130EnsureSearchClusters(data);
    const touched = clusters.some((row) =>
      [
        "product",
        "cluster",
        "mainQueries",
        "intent",
        "clientLanguage",
        "hiddenNeed",
        "demandSegments",
      ].some((key) => String(row[key] || "").trim()),
    );
    if (!touched) return "not_started";
    const ready = clusters.length
      ? clusters.every((row) =>
          [
            "product",
            "cluster",
            "mainQueries",
            "intent",
            "clientLanguage",
            "hiddenNeed",
            "demandSegments",
          ].every((key) => String(row[key] || "").trim()),
        )
      : false;
    return ready ? "ready" : "in_progress";
  }
  if (step.customRender === "offerJtbd") {
    const tasks = data.offerTasks || [];
    if (!tasks.length || !tasks.some((t) => String(t.name || "").trim()))
      return "not_started";
    const hasOffer = tasks.some((t) =>
      (t.offers || []).some((o) => String(o.of0 || "").trim()),
    );
    if (hasOffer) return "ready";
    return "in_progress";
  }
  const fields = guruRequiredFields(step.fields || []);
  const fieldsFilled = fields.filter((f) =>
    String(data[f.k] || "").trim(),
  ).length;
  let tableFilled = false,
    tableReady = false;
  if (step.table) {
    const rows = data[step.tableKey] || [];
    tableFilled = rows.some((r) =>
      guruRequiredRecordValues(r).some((v) => String(v || "").trim()),
    );
    tableReady =
      rows.length > 0 &&
      rows.some((r) =>
        guruRequiredRecordValues(r).every((v) => String(v || "").trim()),
      );
  }
  const anyFilled = fieldsFilled > 0 || tableFilled;
  if (!anyFilled) return "not_started";
  const allFieldsReady = !fields.length || fieldsFilled === fields.length;
  const allTableReady = !step.table || tableReady;
  if (allFieldsReady && allTableReady) return "ready";
  return "in_progress";
}

