function g4ReadinessHtml() {
  const d = ensureGate4State();
  const allStatuses = G4_BLOCKS.slice(0, 4).map((b) => g4BlockStatus(b.key));
  const sel = (
    field,
    value,
  ) => `<select class="g1-input is-filled" data-g4-block="readiness" data-g4-field="${escapeAttr(field)}">
    <option value=""${!value ? " selected" : ""}>—</option>
    <option value="да"${value === "да" ? " selected" : ""}>да</option>
    <option value="нет"${value === "нет" ? " selected" : ""}>нет</option>
  </select>`;
  const allBlocksReady = allStatuses.every((s) => s === "ready");
  const allChecked =
    d.readiness.qaChecked === "да" &&
    d.readiness.leadsHandling === "да" &&
    d.readiness.launchConfirmed === "да";
  return `<p class="g1-task">Финальный QA перед стартом. Бинарно: да / нет.</p>
    <div class="g4-upstream">
      <div class="g4-upstream-title">Статусы блоков Gate 4</div>
      ${G4_BLOCKS.slice(0, 4)
        .map(
          (b, i) =>
            `<div class="g4-readonly"><span class="g4-readonly-label">${escapeHtml(b.title)}</span><span class="status-pill status-${allStatuses[i]}" style="font-size:12px">${escapeHtml(STATUS_LABELS[allStatuses[i]] || allStatuses[i])}</span></div>`,
        )
        .join("")}
    </div>
    <div class="g1-fields-grid" style="margin-top:16px">
      <label class="g1-field"><span>Предзапусковый QA пройден</span>${sel("qaChecked", d.readiness.qaChecked)}</label>
      <label class="g1-field"><span>Обработка заявок настроена</span>${sel("leadsHandling", d.readiness.leadsHandling)}</label>
      <label class="g1-field"><span>Подтверждение запуска</span>${sel("launchConfirmed", d.readiness.launchConfirmed)}</label>
    </div>
    ${allBlocksReady && allChecked ? '<div class="g4-launch-ok">Все блоки готовы. Можно запускать.</div>' : ""}
    <p class="g1-task" style="font-style:italic;margin-top:8px">Готово, когда все три пункта — «да».</p>`;
}

const G4_RENDERERS = {
  offer: g4OfferHtml,
  landing: g4LandingHtml,
  creatives: g4CreativesHtml,
  launchParams: g4LaunchParamsHtml,
  readiness: g4ReadinessHtml,
};

function renderGate4Redesign(gate) {
  ensureGate4State();
  const d = state.gate4;
  els.contentArea.innerHTML = `<div class="g1-redesign">
    ${G4_BLOCKS.map((block) => {
      const isOpen = Boolean(d.openSteps[block.key]);
      const status = g4BlockStatus(block.key);
      return `<section class="g1-section ${isOpen ? "is-open" : ""}">
        <button class="g1-section-header" data-g4-toggle="${escapeAttr(block.key)}">
          <span class="g1-section-left">
            <span class="g1-section-title">${escapeHtml(block.title)}</span>
          </span>
          <span class="status-pill status-${status}">${escapeHtml(STATUS_LABELS[status] || status)}</span>
        </button>
        ${isOpen ? `<div class="g1-section-body">${G4_RENDERERS[block.key]()}</div>` : ""}
      </section>`;
    }).join("")}
  </div>`;
  bindGate4Events();
  renderGateNav();
}

function bindGate4Events() {
  document.querySelectorAll("[data-g4-toggle]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const key = btn.dataset.g4Toggle;
      const d = ensureGate4State();
      d.openSteps[key] = !d.openSteps[key];
      saveState();
      renderGate();
    });
  });
  document
    .querySelectorAll("[data-g4-block][data-g4-field]")
    .forEach((input) => {
      const handler = (e) => {
        const block = e.target.dataset.g4Block;
        const field = e.target.dataset.g4Field;
        const d = ensureGate4State();
        d[block][field] = e.target.value;
        flashSaving();
        if (e.target.tagName === "SELECT") {
          renderGate();
        } else {
          const cls = e.target.value.trim() ? "is-filled" : "is-empty";
          e.target.classList.remove("is-filled", "is-empty");
          e.target.classList.add(cls);
          renderGateNav();
        }
      };
      input.addEventListener("input", handler);
      input.addEventListener("change", handler);
    });
  document.querySelectorAll("[data-g4-add-impl]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const d = ensureGate4State();
      d.implementations.push({ channel: "", type: "", name: "", message: "", landing: "", budget: "", status: "not_started", source: "" });
      saveState();
      renderGate();
    });
  });
  document.querySelectorAll("[data-g4-impl-from-channels]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const d = ensureGate4State();
      const existing = new Set(d.implementations.map((i) => i.channel.trim()).filter(Boolean));
      g4MentionedChannels().active.forEach((c) => {
        if (existing.has(c.name)) return;
        d.implementations.push({ channel: c.name, type: "", name: "", message: "", landing: "", budget: "", status: "not_started", source: "" });
      });
      saveState();
      renderGate();
    });
  });
  document.querySelectorAll("[data-g4-remove-impl]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const d = ensureGate4State();
      d.implementations.splice(Number(btn.dataset.g4RemoveImpl), 1);
      saveState();
      renderGate();
    });
  });
  document.querySelectorAll("[data-g4-impl][data-g4-impl-field]").forEach((input) => {
    const handler = (e) => {
      const d = ensureGate4State();
      const item = d.implementations[Number(e.target.dataset.g4Impl)];
      if (!item) return;
      item[e.target.dataset.g4ImplField] = e.target.value;
      flashSaving();
      if (e.target.tagName === "SELECT") {
        renderGate();
      } else {
        const cls = e.target.value.trim() ? "is-filled" : "is-empty";
        e.target.classList.remove("is-filled", "is-empty");
        e.target.classList.add(cls);
        renderGateNav();
      }
    };
    input.addEventListener("input", handler);
    input.addEventListener("change", handler);
  });
}

const __prevRenderSemanticGateAccordionG4 = renderSemanticGateAccordion;
renderSemanticGateAccordion = function (gate, cards) {
  if (isGate4(gate)) {
    renderGate4Redesign(gate);
    return;
  }
  __prevRenderSemanticGateAccordionG4(gate, cards);
};

/*
  Gate 0 → Gate 1: справочные подсказки (G0 hints)
  Не автозаполнение. Только popover с данными из Gate 0 рядом с полями Gate 1.
*/

function readGate0Value(key) {
  if (!state) return "";
  const p = state.project || {};
  const se = state.sharedEvidence || {};
  const map = {
    product: () => p.whatSell || se["что_продаем"] || "",
    audience: () => p.targetSegment || se["кому_продаем"] || "",
    client_result: () => p.clientResult || se["ради_какого_результата"] || "",
    geo: () => p.geography || "",
    project_name: () => p.name || "",
    website: () => p.website || "",
    niche: () => p.niche || "",
    rational_coverage: () =>
      p.offerRationalCoverage || se["offer_rational_coverage"] || "",
    irrational_driver: () =>
      p.offerIrrationalDriver || se["offer_irrational_driver"] || "",
    social_mechanism: () =>
      p.offerSocialMechanism || se["offer_social_mechanism"] || "",
    positioning: () =>
      p.positioningStatement || se["positioning_statement"] || "",
    usp: () => p.usp || se["positioning_usp"] || "",
    main_keywords: () =>
      p.searchMainKeywords || se["search_main_keywords"] || "",
    priority_clusters: () =>
      p.searchPriorityClusters || se["search_priority_clusters"] || "",
    brand_queries: () =>
      p.searchBrandQueries || se["search_brand_queries"] || "",
    irrelevant_queries: () =>
      p.searchIrrelevantQueries || se["search_irrelevant_queries"] || "",
    current_offers: () => p.currentOffers || se["current_offers"] || "",
    current_ctas: () => p.currentCtas || se["current_ctas"] || "",
    primary_target_action: () =>
      p.primaryTargetAction || se["primary_target_action"] || "",
    services_list: () => p.whatSell || se["что_продаем"] || "",
  };
  return (map[key] ? map[key]() : "").trim();
}

